/**
 * The types `save/bots/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    UserBotDataSaveRow, BotSaveRow, BotPresetSaveExtract, BotSynchronicitySaveExtract, BotsSaveExtract
 * depends    src/data/bots/types
 * used by    src/save/bots/index, src/save/bots/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { BotLabLevels } from '../../data/bots/types'

// from read.ts

export interface UserBotDataSaveRow {
  unlocked: boolean
  active: boolean
  levels: number[]
  selectedLevels: number[]
  plusUnlocked: boolean
  plusLevel: number
}

export interface BotSaveRow {
  index: number
  name: string | null
  label: string
  unlocked: boolean
  active: boolean
  statLevels: number[]
  plusUnlocked: boolean
  plusLevel: number
}

export interface BotPresetSaveExtract {
  index: number
  name: string
  bots: BotSaveRow[]
}

/** Synchronicity as the save holds it: whether it is unlocked, its level, and its slots. */
export interface BotSynchronicitySaveExtract {
  /** Whether the save carries synchronicity at all; a save from before it does not. */
  inSave: boolean
  unlocked: boolean
  level: number
  /** `synchronicityLevel + 2` once unlocked, 0 before. */
  slotCount: number
  /** The active preset's slots, in order: the bot in each, or `null` for an empty slot. */
  slots: (string | null)[]
  /** The bots in the active preset's slots, in slot order. */
  bots: string[]
  /** Slots in the active preset with a bot in them. */
  occupiedSlots: number
  /** Slot values that name no known bot, reported rather than dropped. */
  unrecognizedSlotValues: unknown[]
  stonesSpentOnBetaSynchronicity: number
}

export interface BotsSaveExtract {
  currentPreset: number | null
  presetNames: string[]
  totalCoins: unknown
  totalDamage: unknown
  totalStuns: unknown
  totalStonesSpent: unknown
  totalMedalsSpent: unknown
  unlocked: boolean[]
  active: boolean[]
  /** Flat stat-level row for the in-game active preset (legacy layout). */
  levels: number[]
  /** Bot rows for the in-game active preset. */
  bots: BotSaveRow[]
  /** All gameplay presets stored in the save. */
  presets: BotPresetSaveExtract[]
  labLevels: Record<string, BotLabLevels>
  synchronicity: BotSynchronicitySaveExtract
  usesV28BotData: boolean
  warnings: string[]
}
